// More of std: string searching, splitting and editing, integer helpers, char conversions.
fn main() {
    let s = String::from("  Hello, World! hello  ");
    let t = s.trim();
    println!("{:?}", t.find("llo"));
    println!("{:?}", t.rfind('l'));
    println!("{:?}", t.split_once(", "));
    println!("{:?}", t.strip_prefix("Hello"));
    println!("{:?}", t.strip_suffix("xx"));
    println!("{}", t.trim_matches('H'));
    println!("{}", t.trim_start_matches("Hel"));
    println!("{:?}", t.char_indices().filter(|(_, c)| c.is_uppercase()).collect::<Vec<_>>());
    println!("{:?}", t.bytes().take(3).collect::<Vec<u8>>());
    println!("{}", t.chars().count());
    println!("{}", t.contains('W'));
    println!("{}", t.starts_with('H'));
    println!("{}", t.replace('l', "L"));
    println!("{:?}", t.splitn(2, ' ').collect::<Vec<_>>());
    println!("{:?}", t.rsplit(' ').collect::<Vec<_>>());
    println!("{}", t.to_owned() + "!");
    println!("{}", t.repeat(2));
    println!("{:?}", t.chars().position(|c| c == ','));
    println!("{}", t.is_empty());
    let mut u = String::with_capacity(10);
    u.push_str("abc");
    u.insert(0, 'x');
    u.insert_str(1, "yz");
    let popped = u.pop();
    println!("{} {:?}", u, popped);
    u.truncate(2);
    u.clear();
    println!("[{}]", u);
    let words = vec!["a", "b", "c"];
    println!("{}", words.concat());
    println!("{}", words.join("-"));
    let n: i32 = -17;
    println!("{} {} {} {}", n.abs(), n.pow(2), n.signum(), n.rem_euclid(5));
    println!("{} {}", i32::MAX, u8::MAX);
    println!("{:?} {:?}", 200u8.checked_add(100), 5u32.checked_sub(6));
    println!("{} {}", 250u8.saturating_add(10), 250u8.wrapping_add(10));
    println!("{}", 7.5f64.floor() as i32);
    println!("{:?}", "a b".split(' ').map(String::from).collect::<Vec<String>>());
    let v = vec![3, 1, 2];
    println!("{:?} {:?}", v.iter().min(), v.contains(&2));
    let mut w = v.clone();
    w.sort_unstable_by(|a, b| b.cmp(a));
    println!("{:?} {:?}", w, w.binary_search_by(|p| 2.cmp(p)));
    println!("{:?}", v.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(","));
    println!("{:?}", v.first().copied());
    let total: usize = v.len() * 2;
    println!("{}", total);
    let c = 'a';
    println!("{} {}", c as u32, (c as u8 + 1) as char);
    println!("{:?}", char::from_digit(7, 10));
    println!("{}", std::cmp::max(3, 9));
    println!("{}", std::cmp::min(3, 9));
}
